// MenuContent.tsx
import { ReactElement } from 'react';
import { routes, getRoutesBySubcategory } from '../index';
import { iconConfig } from './scripts/useHover';
import { useAccordion, useAccordionChild } from './scripts/useAcordion';

interface MenuContentProps {
  isMobile: boolean;
  currentRouteId: string;
  onCourseClick: (courseId: string) => void;
}

export default function MenuContent({
  isMobile,
  currentRouteId,
  onCourseClick
}: MenuContentProps): ReactElement {
  const { hoverStates, handleMouseEnter, handleMouseLeave } = useIconHover();
  const { openSections, toggleSection } = useAccordion();
  const { openSectionsChild, toggleSectionChild } = useAccordionChild();

  // Список курсов
  const designCourses = getRoutesBySubcategory('courses', 'design');
  const developmentCourses = getRoutesBySubcategory('courses', 'development');
  const analyticsCourses = getRoutesBySubcategory('courses', 'analytics');
  const marketingCourses = getRoutesBySubcategory('courses', 'marketing');

  // Общие классы для адаптации
  const containerClass = isMobile ? 'mobile-accordions' : 'list-of-services';
  const accordionClass = isMobile ? 'mobile-accordion-item' : '';
  const contentClass = isMobile ? 'mobile-content' : 'accordion-content-coures';

  return (
    <div className={containerClass}>
      {/* АККОРДЕОН "КУРСЫ" */}
      <div 
        className={`coures ${accordionClass} ${openSections.courses ? 'active' : ''}`}
        onMouseEnter={() => !isMobile && handleMouseEnter('courses')}
        onMouseLeave={() => !isMobile && handleMouseLeave('courses')}
        onClick={() => toggleSection('courses')}
      >
        <img src={
          openSections.courses ? iconConfig.courses.hover :
          hoverStates.courses ? iconConfig.courses.hover :
          iconConfig.courses.default
        } />
        <p>Курсы</p>
      </div>
      
      <div className={`${contentClass} ${openSections.courses ? 'open' : ''}`}>
        <div className='accordion-content-inner'>
          {/* ... ВЕСЬ ВАШ КОД СПИСКОВ (дизайн, разработка и т.д.) ... */}
          {/* Просто скопируйте сюда весь контент из оригинального list-of-services */}
        </div>
      </div>

      {/* АККОРДЕОН "СЕРВИСЫ" */}
      <div className={`services ${accordionClass} ${openSections.services ? 'active' : ''}`}>
        {/* Аналогично... */}
      </div>

      {/* АККОРДЕОН "КНИГИ" */}
      {/* АККОРДЕОН "ТОВАРЫ" */}
    </div>
  );
}